 50	  backgroundcolor=draftnotebg,
 51	  linecolor=draftnotebar,
 52	  topline=false,bottomline=false,rightline=false,
 53	  linewidth=2.5pt,
 54	  innerleftmargin=8pt,innerrightmargin=8pt,
 55	  innertopmargin=6pt,innerbottommargin=6pt,
 56	  skipabove=8pt,skipbelow=8pt
 57	]{draftnotebox}
 58	\newcommand{\note}[1]{%
 59	\begin{draftnotebox}%
 60	{\sffamily\footnotesize\color{draftnotebar}\textsc{Draft note}}\\[2pt]
 61	{\sffamily\small #1}%
 62	\end{draftnotebox}}
